    Bug 1960263 - Flush mbox file before truncation when rolling back bad writes. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D245371

diff --git a/mailnews/base/src/MboxMsgOutputStream.cpp b/mailnews/base/src/MboxMsgOutputStream.cpp
index c6eb1bcf3d8..af391e71c25 100644
--- a/mailnews/base/src/MboxMsgOutputStream.cpp
+++ b/mailnews/base/src/MboxMsgOutputStream.cpp
@@ -345,9 +345,13 @@ nsresult MboxMsgOutputStream::InternalClose() {
     rv = NS_ERROR_UNEXPECTED;
   }

+  // Make sure everything is flushed out before we truncate (Bug 1960252).
+  if (NS_SUCCEEDED(rv)) {
+    rv = mInner->Flush();
+  }
+
   if (NS_SUCCEEDED(rv)) {
     // Attempt to truncate the target file back to our start position.
-    nsresult rv;
     rv = mSeekable->Seek(nsISeekableStream::NS_SEEK_SET, mStartPos);
     if (NS_SUCCEEDED(rv)) {
       rv = mSeekable->SetEOF();
@@ -358,8 +362,8 @@ nsresult MboxMsgOutputStream::InternalClose() {
   }

   if (mCloseInnerWhenDone) {
-    // Don't want to obscure a previous error
     nsresult rv2 = mInner->Close();
+    // Don't want to obscure a previous error
     if (NS_SUCCEEDED(rv)) {
       rv = rv2;
     }
